using System;using System.Collections.Generic;using BeamScheduleFormatter;
class ProgramOfWorksTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}static void Near(double a,double b,string m){Check(Math.Abs(a-b)<.0000001,m);}
 static void Main(){var door=new OpeningItem{Id="D1",Description="Wood door",Wall="W1",Material="Wood",Kind="Door",Width=1,Height=2.1,Quantity=2,JambDepth=.15,JambThickness=.05,LeafThickness=.04,Faces=2,LocksPerUnit=1,HingesPerUnit=3};door.Validate();Near(door.Area,4.2,"Overall opening quantity");Near(door.LeafWidth,.9,"Jamb deducted from leaf width");Near(door.LeafHeight,2.05,"Door top jamb deducted");Near(door.LeafPaint,7.911,"Both leaf faces and edges");Near(door.JambPaint,2.6,"Door jamb three sides");Check(door.Locks==2&&door.Hinges==6,"Hardware multiplied once");
 var window=new OpeningItem{Id="AW1",Description="Aluminum window",Wall="w1",Material="Aluminum",Kind="Window",Width=1.2,Height=1,Quantity=1,LocksPerUnit=0,HingesPerUnit=0};window.Validate();Near(window.LeafPaint+window.JambPaint,0,"Aluminum paint excluded");var wall=new WallItem{Id="W1",Description="Wall",Length=5,Height=3,Quantity=2,BlockWidth=.4,BlockHeight=.2};var list=new[]{door,window};Near(wall.Gross,30,"Wall group quantity");Near(wall.Deduction(list),5.4,"Wood + aluminum deduction once, case-insensitive");Near(wall.Net(list),24.6,"Net area");Check(wall.Blocks(list)==308,"Ceiling whole blocks");window.Wall="OTHER";Near(wall.Deduction(list),4.2,"Other walls not deducted");door.Quantity=100;bool rejected=false;try{wall.Net(list);}catch{rejected=true;}Check(rejected,"Excess opening area rejected");door.Quantity=1;door.Width=.05;rejected=false;try{door.Validate();}catch{rejected=true;}Check(rejected,"Impossible jamb/leaf dimensions rejected");Console.WriteLine("PASS: "+checks+" door/window paint, jamb, hardware, linked wall deductions and block takeoff checks.");}
}
